-- =============================================================================
-- Search Platform V2 — configured Business Processes for certification
-- =============================================================================
-- Publishes the certification tenant's COMPLETE department process configuration:
-- the representative seed's Enrollment process plus two extra processes, so a
-- child can be found in three configured processes and Search can resolve every
-- label from tenant configuration.
--
-- Published through the CANONICAL path — a validated draft handed to
-- `publish_business_process_revision_v1` — not by writing
-- `departments.metadata.lifecycle_builder_v1` directly, and with NO guard bypass.
--
-- ⚠ WHY THIS FILE CARRIES THE WHOLE CONFIGURATION, NOT JUST THE EXTRA PROCESSES
--
-- Publication REPLACES the department's projection; it never merges. An earlier
-- revision of this file published only three bare processes — no `work_views_v1`,
-- no `active_process_id`, no stage `grain` — which DELETED the seed's Enrollment
-- configuration. Every work unit in the tenant then answered:
--
--     no_active_view — "no Work View is configured for this Business Process"
--
-- so no Focus Panel could compose anywhere, and the Search → Focus Panel scenarios
-- were unprovable. That damage is also NOT self-healing: once a department has
-- published, `guard_lifecycle_builder_projection` refuses the representative
-- seed's direct write, so re-seeding cannot restore it. A partial payload here is
-- a one-way door.
--
-- The Enrollment process below is the seed's, verbatim
-- (`supabase/seed/local_representative_seed.sql` Section 4) — itself generated by
-- `web/lib/businessProcessTemplates/enrollmentProcessTemplate.ts` and validated by
-- `parseLifecycleBuilderV1`. Regenerate this file when that changes.
--
-- This is the anti-hardcoding control: the names below exist ONLY here, in
-- configuration. `web/lib/search` contains none of them — a test greps for that.
-- =============================================================================

\set ON_ERROR_STOP on

DO $publish$
DECLARE
    v_org      uuid;
    v_dept     uuid;
    v_actor    uuid;
    v_draft    uuid;
    v_rev      uuid;
    v_res      jsonb;
    v_checksum text := 'search-cert-department-processes-v2';
BEGIN
    SELECT id INTO v_org FROM public.orgs WHERE slug = 'northwind-early-learning';
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'Refusing to run outside the disposable certification tenant.';
    END IF;

    SELECT id INTO v_dept
      FROM public.departments
     WHERE org_id = v_org AND is_active IS NOT FALSE
     ORDER BY sort_order NULLS LAST, key
     LIMIT 1;
    IF v_dept IS NULL THEN
        RAISE EXCEPTION 'No active department to carry process configuration.';
    END IF;

    SELECT user_id INTO v_actor FROM public.user_roles
     WHERE org_id = v_org ORDER BY role LIMIT 1;

    -- Law 4: the draft must be opened against the CURRENT publication, or the RPC
    -- refuses it as stale. NULL on a tenant that has never published.
    SELECT cp.revision_id INTO v_rev
      FROM public.configuration_publications cp
     WHERE cp.org_id = v_org AND cp.domain_key = 'business_process' AND cp.subject_id = v_dept
     ORDER BY cp.revision_number DESC
     LIMIT 1;

    -- Publication is NOT idempotent by call, but it IS by checksum: an identical
    -- payload from the same lineage returns the live revision and writes nothing.
    -- So this can run on every certification pass.
    SELECT id INTO v_draft FROM public.business_process_drafts
     WHERE org_id = v_org AND department_id = v_dept LIMIT 1;

    IF v_draft IS NULL THEN
        INSERT INTO public.business_process_drafts
            (org_id, department_id, payload, draft_status, base_revision_id, validated_at, validation_errors)
        VALUES (v_org, v_dept, $payload${"version":1,"active_process_id":"00000000-0000-4000-8000-000000000021","processes":[{"id":"00000000-0000-4000-8000-000000000021","key":"enrollment","name":"Enrollment","description":"Lead to enrolled — inquiry, tour, decision, placement.","primary_entity":"opportunity","sort_order":0,"is_active":true,"tracks_v1":{"version":1,"tracks":[{"key":"family_track","label":"Family Track","subject":"family_case","sort_order":0},{"key":"child_track","label":"Child Track","subject":"child_enrollment_track","sort_order":1}],"split_rules":[{"version":1,"from_track_key":"family_track","from_stage_key":"decision","into_track_key":"child_track","per_subject_outcomes":[{"outcome_key":"waitlist","label":"Waitlist","target_stage_key":"waitlist"},{"outcome_key":"enrolling","label":"Enrolling","target_stage_key":"enrolling"},{"outcome_key":"closed_withdrawn","label":"Closed / Withdrawn","target_stage_key":"closed_withdrawn"},{"outcome_key":"no_action","label":"No action — keep with family","target_stage_key":null}]}]},"work_views_v1":[{"id":"new_leads","label":"New Leads","mission":"Respond to every new family inquiry before it goes cold.","compat_queue_key":"new_leads","display_order":1,"visible_in_runtime":true,"sort_v1":{"field_key":"updated_at","direction":"desc"},"sorts_v1":[{"field_key":"updated_at","direction":"desc"}],"row_grain_v1":"family"},{"id":"tours","label":"Tours","mission":"Confirm the visit and record the outcome.","compat_queue_key":"tours","display_order":2,"visible_in_runtime":true,"sort_v1":{"field_key":"updated_at","direction":"asc"},"sorts_v1":[{"field_key":"updated_at","direction":"asc"}],"row_grain_v1":"family"},{"id":"follow_up","label":"Follow Up","mission":"Keep the conversation moving toward a decision.","compat_queue_key":"communications_followup","display_order":3,"visible_in_runtime":true,"sort_v1":{"field_key":"updated_at","direction":"desc"},"sorts_v1":[{"field_key":"updated_at","direction":"desc"}],"row_grain_v1