-- =============================================================================
-- Verification — POSITIVE CONTROL, not just "the rows I wrote are there".
--
-- The old verification asserted only "3 certification processes exist", which the
-- configuration-destroying payload satisfied perfectly. What actually matters is
-- that the tenant remains OPERATIONALLY COMPOSABLE: an active process, visible
-- Work Views with a declared row grain, and stages that carry an operating plan.
-- =============================================================================
DO $verify$
DECLARE
    v_org     uuid;
    v_meta    jsonb;
    v_active  jsonb;
    v_procs   int;
    v_views   int;
    v_stages  int;
    v_labels  text;
BEGIN
    SELECT id INTO v_org FROM public.orgs WHERE slug = 'northwind-early-learning';

    SELECT d.metadata -> 'lifecycle_builder_v1' INTO v_meta
      FROM public.departments d
     WHERE d.org_id = v_org AND d.is_active IS NOT FALSE
     ORDER BY d.sort_order NULLS LAST, d.key
     LIMIT 1;

    IF v_meta IS NULL THEN
        RAISE EXCEPTION 'no published process configuration on the certification department';
    END IF;

    IF nullif(btrim(coalesce(v_meta ->> 'active_process_id', '')), '') IS NULL THEN
        RAISE EXCEPTION 'published configuration names no active_process_id — every Work Unit will answer no_active_view';
    END IF;

    SELECT count(*), string_agg(p ->> 'name', ', ' ORDER BY p ->> 'name')
      INTO v_procs, v_labels
      FROM jsonb_array_elements(v_meta -> 'processes') p
     WHERE (p ->> 'is_active')::boolean IS TRUE;

    IF v_procs < 3 THEN
        RAISE EXCEPTION 'process configuration incomplete: % active processes, need at least 3', v_procs;
    END IF;

    SELECT p INTO v_active
      FROM jsonb_array_elements(v_meta -> 'processes') p
     WHERE p ->> 'id' = v_meta ->> 'active_process_id';

    IF v_active IS NULL THEN
        RAISE EXCEPTION 'active_process_id % names no process in the published projection', v_meta ->> 'active_process_id';
    END IF;

    -- A visible Work View with a DECLARED row grain. Without the declaration the runtime
    -- derives grain from the stages a lens filters on; a lens with no stage predicate spans
    -- both family and child stages and law G-1 refuses the surface as grain-ambiguous.
    SELECT count(*) INTO v_views
      FROM jsonb_array_elements(coalesce(v_active -> 'work_views_v1', '[]'::jsonb)) v
     WHERE coalesce((v ->> 'visible_in_runtime')::boolean, true) IS TRUE
       AND nullif(btrim(coalesce(v ->> 'row_grain_v1', '')), '') IS NOT NULL;

    IF v_views = 0 THEN
        RAISE EXCEPTION 'the active process publishes no visible Work View with a declared row grain — no Focus Panel can compose';
    END IF;

    SELECT count(*) INTO v_stages
      FROM jsonb_array_elements(coalesce(v_active -> 'stages', '[]'::jsonb)) s
     WHERE (s ->> 'is_active')::boolean IS TRUE
       AND s ? 'stage_operating_plan_v1';

    IF v_stages = 0 THEN
        RAISE EXCEPTION 'the active process publishes no stage with an operating plan — every subject refuses as no_truthful_primary_action';
    END IF;

    RAISE NOTICE 'Published configuration verified: % processes (%), % visible grain-declared Work Views, % stages with an operating plan.',
        v_procs, v_labels, v_views, v_stages;
END $verify$;
